// --- Safety Guardrails for Thumbnail and Sandbox ---
if (typeof width === 'undefined') { var width = 1280; }
if (typeof height === 'undefined') { var height = 720; }


// --- Global Variables for Uncler M Variants ---
var uM_colors = ["#064e3b", "#10b981", "#6ee7b7", "#0f766e", "#134e4a"];
var speedMult = 1.0;
var lineScale = 1.0;
var dynamicShift = 0;
var scalePulse = 1.0;
var rotAngle = 0;
var gridOffset = 0;
var uM_rot = 0;

// === Inspired by 'Boxfacesrecursionpathstroke' by 'Jean Carvalho Art' ===
// Created as variant #3 by Uncler M
// Infused with creative algorithmic modifications.

// === Tab: mySketch ===
let n, tam, maxtam;
n = 7;
let rx = [],
	ry = [],
	rz = [];
let esp = 10;
let rodar = false;

function setup() {
	tam = [window.innerWidth, window.innerHeight];
	maxtam = min(...tam);
	d = maxtam / 2 / n / sqrt(2);

	createCanvas(tam[0], tam[1], WEBGL);
	angleMode(DEGREES);
	strokeWeight(2);

	for (let i = 0; i < esp * n; i++) {
		rz[i] = 0;
		rx[i] = 0;
		ry[i] = 0;
	}
}

function draw() {
  // === Variant 3: Fractal Orbit Matrix ===
  gridOffset = noise(frameCount * 0.01) * 80;
  push();
  translate(gridOffset, -gridOffset);

	let aux = clique * 255;
	background(aux);
	fill(aux, aux, aux, 255 / n * 1.5)
	stroke(!clique * 255);

	orbitControl();

	if (!rodar) {
		if (rotationX * rotationY * rotationZ != 0 && rotationX * rotationY * rotationZ != null) {
			rodar = true;
		}
	}

	for (let i = esp * n; i > 0; i--) {
		rz[i] = rz[i - 1];
		rx[i] = rx[i - 1];
		ry[i] = ry[i - 1];
	}

	if (rodar) {
		rz[0] = rotationZ;
		rx[0] = rotationX;
		ry[0] = rotationY;
	} else {
		ry[0] = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, tam[0], 0, -360);
		rx[0] = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, tam[1], 0, -180);
	}


	for (let i = 0; i < n; i++) {

		if (!i) {
			push();
			rotateZ(rz[esp * i]);
			rotateX(rx[esp * i]);
			rotateY(ry[esp * i]);
			box(2 * d);
			pop();
		} else {
			push();
			rotateZ(rz[esp * i]);
			rotateX(rx[esp * i]);
			rotateY(ry[esp * i]);

			let ad = (i + 1) * d * abs(cos(frameCount)) + d;

			beginShape();
			vertex(-d, -d, ad);
			vertex(-d, d, ad);
			vertex(d, d, ad);
			vertex(d, -d, ad);
			endShape(CLOSE);

			beginShape();
			vertex(-d, -d, -ad);
			vertex(-d, d, -ad);
			vertex(d, d, -ad);
			vertex(d, -d, -ad);
			endShape(CLOSE);

			beginShape();
			vertex(ad, -d, -d);
			vertex(ad, -d, d);
			vertex(ad, d, d);
			vertex(ad, d, -d);
			endShape(CLOSE);

			beginShape();
			vertex(-ad, -d, -d);
			vertex(-ad, -d, d);
			vertex(-ad, d, d);
			vertex(-ad, d, -d);
			endShape(CLOSE);

			beginShape();
			vertex(-d, ad, -d);
			vertex(-d, ad, d);
			vertex(d, ad, d);
			vertex(d, ad, -d);
			endShape(CLOSE);

			beginShape();
			vertex(-d, -ad, -d);
			vertex(-d, -ad, d);
			vertex(d, -ad, d);
			vertex(d, -ad, -d);
			endShape(CLOSE);

			pop();
		}
	}


  pop();
}

clique = true;

function mouseClicked() {
	clique = !clique;
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
